CREATE TABLE "crm_opportunities"("id" SERIAL PRIMARY KEY,"title" TEXT NOT NULL,"company" TEXT,"contact_name" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"customer_id" INTEGER REFERENCES "customers"("id") ON DELETE SET NULL,"stage" TEXT NOT NULL DEFAULT 'lead',"status" TEXT NOT NULL DEFAULT 'open',"value" DOUBLE PRECISION NOT NULL DEFAULT 0,"probability" INTEGER NOT NULL DEFAULT 10,"source" TEXT,"owner" TEXT NOT NULL,"expected_at" DATE,"lost_reason" TEXT,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX "crm_opportunities_stage_status_expected_at_idx" ON "crm_opportunities"("stage","status","expected_at");CREATE INDEX "crm_opportunities_customer_id_idx" ON "crm_opportunities"("customer_id");
CREATE TABLE "crm_activities"("id" SERIAL PRIMARY KEY,"opportunity_id" INTEGER NOT NULL REFERENCES "crm_opportunities"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"subject" TEXT NOT NULL,"notes" TEXT,"due_at" TIMESTAMPTZ,"completed_at" TIMESTAMPTZ,"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "crm_activities_opportunity_id_due_at_idx" ON "crm_activities"("opportunity_id","due_at");
CREATE TABLE "crm_stage_history"("id" SERIAL PRIMARY KEY,"opportunity_id" INTEGER NOT NULL REFERENCES "crm_opportunities"("id") ON DELETE CASCADE,"from_stage" TEXT,"to_stage" TEXT NOT NULL,"actor" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "crm_stage_history_opportunity_id_created_at_idx" ON "crm_stage_history"("opportunity_id","created_at");
